// Everything you are meant to edit lives in this node.

const categories = ['cs.CL', 'cs.LG', 'cs.AI'];

// Two tiers, because one flat list is either leaky or deaf.
// STRONG terms are unambiguous — nothing outside this field says 'sandbagging'.
const strongKeywords = [
  'jailbreak', 'prompt injection', 'red team', 'red-team',
  'safety alignment', 'alignment faking', 'emergent misalignment', 'deceptive alignment',
  'reward hacking', 'specification gaming', 'sandbagging', 'scheming',
  'scalable oversight', 'ai control', 'monitorability', 'chain-of-thought monitoring',
  'model organism', 'latent knowledge', 'constitutional ai', 'weak-to-strong'
];

// WEAK terms are real interests that other fields also use: a memecoin-fraud paper
// matched 'backdoor', a decision-tree paper matched 'interpretability'. These count
// only when the abstract is also clearly about language models.
const weakKeywords = [
  'interpretability', 'probing', 'auditing', 'backdoor', 'data poisoning',
  'unlearning', 'guardrail', 'refusal', 'harmful', 'adversarial attack',
  'fine-tuning attack', 'safety training', 'oversight', 'steering vector',
  'sparse autoencoder', 'activation'
];

const contextTerms = [
  'language model', 'llm', 'llms', 'gpt', 'claude', 'llama', 'chatbot',
  'foundation model', 'instruction-tuned', 'rlhf', 'chain-of-thought', 'frontier model'
];

// Given to the scorer so it judges against your actual interests, not "is this good".
const interests =
  'Empirical AI safety and alignment of large language models: jailbreaks and defences, ' +
  'emergent misalignment, reward hacking, chain-of-thought monitorability, AI control and ' +
  'oversight protocols, data poisoning and backdoors, alignment auditing, and mechanistic ' +
  'interpretability applied to safety. Prefers papers with experiments over position pieces.';

const settings = {
  categories,
  strongKeywords,
  weakKeywords,
  contextTerms,
  interests,
  minScore: 4,
  // A single day is ~200-400 papers across these three categories, so 100 would
  // skip most of it: the run would take the newest 100, move the watermark past
  // the rest, and never come back for them. 600 leaves room for a missed day.
  maxResults: 600,
  dryRun: true,
  ingestUrl: 'http://localhost:8000/ingest',
  scoreModel: 'claude-haiku-4-5'
};

const query = categories.map((c) => `cat:${c}`).join('+OR+');
settings.arxivUrl =
  'http://export.arxiv.org/api/query?search_query=' + query +
  '&sortBy=submittedDate&sortOrder=descending&max_results=' + settings.maxResults;

return [{ json: settings }];

// New entries only, then the cheap filter. Anything that fails the keyword
// test never reaches the model, which is what keeps the daily cost in cents.

const cfg = $('Settings').first().json;
const state = $getWorkflowStaticData('global');
const lastSeenId = state.lastSeenId || null;

const feed = $input.first().json.data.feed || {};
let entries = feed.entry || [];
if (!Array.isArray(entries)) entries = [entries];

const text = (v) => {
  if (Array.isArray(v)) v = v[0];
  if (v && typeof v === 'object') v = v._ ?? '';
  return String(v ?? '').replace(/\s+/g, ' ').trim();
};

const seen = [];
let caughtUp = false;
for (const entry of entries) {
  const absUrl = text(entry.id);
  const arxivId = absUrl.split('/abs/')[1];
  if (!arxivId) continue;
  if (lastSeenId && arxivId === lastSeenId) { caughtUp = true; break; }
  seen.push({
    arxivId,
    absUrl,
    pdfUrl: absUrl.replace('/abs/', '/pdf/'),
    title: text(entry.title),
    abstract: text(entry.summary),
    published: text(entry.published)
  });
}

// If the whole page was new we never reached the watermark, so older papers fell
// off the end of the window and are gone for good. Raise maxResults if this fires.
if (lastSeenId && !caughtUp) {
  console.log(`WARNING: ${entries.length} results did not reach the last-seen id ${lastSeenId}. Papers may have been skipped — raise maxResults.`);
}

// Committed by Record run, not here: if scoring or ingest fails we would rather
// re-scan tomorrow than skip a day's papers for good.
state.pendingNewestId = seen.length ? seen[0].arxivId : lastSeenId;

const lower = (list) => list.map((k) => k.toLowerCase());
const strongList = lower(cfg.strongKeywords);
const weakList = lower(cfg.weakKeywords);
const contextList = lower(cfg.contextTerms);

const matched = [];
for (const paper of seen) {
  const haystack = (paper.title + ' ' + paper.abstract).toLowerCase();
  const strong = strongList.filter((k) => haystack.includes(k));
  // Weak terms belong to other fields too, so they only count when the abstract
  // is also plainly about language models.
  const hasContext = contextList.some((t) => haystack.includes(t));
  const weak = hasContext ? weakList.filter((k) => haystack.includes(k)) : [];
  const hits = strong.concat(weak);
  if (hits.length) {
    matched.push({ json: { ...paper, matchedKeywords: hits, matchedStrong: strong.length > 0 } });
  }
}

console.log(`arXiv returned ${entries.length}, ${seen.length} new, ${matched.length} matched keywords`);
return matched;

// Pair each model response back with the paper that produced it. Items keep
// their order through an HTTP node, so index alignment is what n8n gives us.

const papers = $('New + keyword filter').all();
const out = [];

$input.all().forEach((item, i) => {
  const paper = papers[i].json;
  let score = 0;
  let why = '';
  try {
    const body = item.json.content?.[0]?.text ?? '';
    const parsed = JSON.parse(body.slice(body.indexOf('{'), body.lastIndexOf('}') + 1));
    score = Number(parsed.score) || 0;
    why = String(parsed.why || '');
  } catch (err) {
    // Fail closed: an unreadable score must not become an ingest. -1 keeps it
    // below any threshold and distinguishable from a real low score in the log.
    console.log(`could not parse score for ${paper.arxivId}: ${err.message}`);
    why = 'score unparseable — skipped, see execution log';
    score = -1;
  }
  out.push({ json: { ...paper, score, why } });
});

return out;

// Commit the watermark and build the digest payload. A messaging node attaches
// here: every field it needs — link, score, and why it matched — is already set.

const cfg = $('Settings').first().json;
const state = $getWorkflowStaticData('global');
const scored = $('Read score').all().map((i) => i.json);

let ingested = [];
try {
  const responses = $('POST /ingest').all().map((i) => i.json);
  const kept = scored.filter((p) => p.score >= cfg.minScore);
  ingested = kept.map((paper, i) => ({
    ...paper,
    ingested: responses[i]?.ingested ?? false,
    alreadyPresent: responses[i]?.already_present ?? false
  }));
} catch (err) {
  // Nothing cleared the threshold, so /ingest never ran. Not an error.
  ingested = [];
}

state.lastSeenId = state.pendingNewestId || state.lastSeenId || null;
state.lastRunAt = new Date().toISOString();

const added = ingested.filter((p) => p.ingested && !p.alreadyPresent);
const digest = added.map((p) => `• ${p.title}\n  ${p.absUrl}\n  why: ${p.why} (matched: ${p.matchedKeywords.join(', ')})`);

return [{
  json: {
    ranAt: state.lastRunAt,
    dryRun: cfg.dryRun,
    lastSeenId: state.lastSeenId,
    considered: scored.length,
    aboveThreshold: ingested.length,
    added: added.length,
    duplicates: ingested.filter((p) => p.alreadyPresent).length,
    message: added.length
      ? `${added.length} paper(s) added today:\n\n${digest.join('\n\n')}`
      : 'No new papers cleared the threshold today.',
    papers: ingested
  }
}];
